<script setup lang="ts">
import { computed,h,onMounted,reactive,ref } from 'vue'
import { NAlert,NButton,NDataTable,NDatePicker,NForm,NFormItem,NIcon,NInput,NInputNumber,NModal,NSelect,NSwitch,NTag,useMessage } from 'naive-ui'
import { Plus,Refresh,Copy } from '@vicons/tabler'
import { api,bytes,stamp } from '../api'
import { initialExpiry } from '../forms'
import ProtocolPreset from './ProtocolPreset.vue'
const props=defineProps<{kind:string}>();const message=useMessage()
const names:Record<string,string>={users:'用户',plans:'套餐',nodes:'节点',machines:'机器'}
const descriptions:Record<string,string>={users:'管理账号、配额与有效期。',plans:'建立套餐，供新用户分配额度与有效期。',nodes:'配置逻辑节点、内核参数与计费倍率。',machines:'一个进程管理多个节点，统一维护机器身份。'}
const rows=ref<any[]>([]),plans=ref<any[]>([]),machines=ref<any[]>([]),busy=ref(false),saving=ref(false),show=ref(false),editing=ref<number|null>(null),error=ref(''),formError=ref(''),secret=ref(''),secretVisible=ref(false),secretID=ref<number|null>(null)
const form=reactive<any>({})
async function load(){busy.value=true;error.value='';try{rows.value=await api('/api/admin/'+props.kind);if(props.kind==='users')plans.value=await api('/api/admin/plans');if(props.kind==='nodes')machines.value=await api('/api/admin/machines')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function open(row?:any){let config=row?.config;if(props.kind==='nodes'&&row){try{config=await api('/api/admin/nodes/'+row.id)}catch(e){message.error((e as Error).message);return}}editing.value=row?.id??null;formError.value='';Object.assign(form,{name:row?.name||'',email:row?.email||'',password:'',role:row?.role||'user',plan_id:row?.plan_id??null,quota_gib:(row?.quota_bytes??50*1073741824)/1073741824,expiry:initialExpiry(row?.expires_at,!!row),active:row?.active??true,days:row?.duration_days??30,price:(row?.price_cents??0)/100,machine_id:row?.machine_id??null,multiplier:(row?.multiplier_milli??1000)/1000,interval:row?.report_interval??60,public_host:row?.public_host||'',config:JSON.stringify(config||{protocol:'vless',listen_ip:'0.0.0.0',server_port:443,network:'tcp',tls:0},null,2)});show.value=true}
async function save(){saving.value=true;formError.value='';try{let body:any
 if(props.kind==='users'){body=editing.value?{active:form.active,quota_bytes:Math.round(form.quota_gib*1073741824),expires_at:form.expiry?new Date(form.expiry).toISOString():null,...(form.password?{password:form.password}:{})}:{email:form.email,password:form.password,role:form.role,plan_id:form.plan_id,quota_bytes:Math.round(form.quota_gib*1073741824),expires_at:form.expiry?new Date(form.expiry).toISOString():null}}
 else if(props.kind==='plans')body={name:form.name,quota_bytes:Math.round(form.quota_gib*1073741824),duration_days:form.days,price_cents:Math.round(form.price*100)}
 else if(props.kind==='nodes')body={name:form.name,machine_id:form.machine_id,active:form.active,multiplier_milli:Math.round(form.multiplier*1000),report_interval:form.interval,public_host:form.public_host,config:JSON.parse(form.config)}
 else body={name:form.name}
 const data=await api('/api/admin/'+props.kind+(editing.value?'/'+editing.value:''),{method:editing.value?'PATCH':'POST',body:JSON.stringify(body)});show.value=false;form.password='';message.success('已保存');if(data.token){secret.value=data.token;secretID.value=data.id;secretVisible.value=true}await load()
 }catch(e){formError.value=(e as Error).message}finally{saving.value=false}}
async function copy(){try{await navigator.clipboard.writeText(secret.value);message.success('已复制')}catch{message.warning('复制失败，请手动选择并复制')}}
const columns=computed<any[]>(()=>{const edit={title:'操作',key:'actions',width:90,render:(r:any)=>h(NButton,{size:'small',quaternary:true,type:'primary',onClick:()=>open(r)},()=> '编辑')}
 if(props.kind==='users')return [{title:'用户',key:'email',minWidth:210},{title:'角色',key:'role',width:100,render:(r:any)=>h(NTag,{size:'small',bordered:false,type:r.role==='admin'?'info':'default'},()=>r.role==='admin'?'管理员':'用户')},{title:'已用 / 额度',key:'quota_bytes',minWidth:200,render:(r:any)=>`${bytes(r.used_bytes)} / ${bytes(r.quota_bytes)}`},{title:'到期时间',key:'expires_at',minWidth:190,render:(r:any)=>stamp(r.expires_at)},{title:'状态',key:'active',width:90,render:(r:any)=>h(NTag,{size:'small',bordered:false,type:r.active?'success':'default'},()=>r.active?'启用':'停用')},edit]
 if(props.kind==='plans')return [{title:'套餐名称',key:'name',minWidth:180},{title:'额度',key:'quota_bytes',minWidth:130,render:(r:any)=>bytes(r.quota_bytes)},{title:'有效期',key:'duration_days',minWidth:110,render:(r:any)=>r.duration_days+' 天'},{title:'标价',key:'price_cents',minWidth:110,render:(r:any)=>'¥ '+(r.price_cents/100).toFixed(2)},edit]
 if(props.kind==='machines')return [{title:'机器 ID',key:'id',width:110},{title:'名称',key:'name',minWidth:180},{title:'关联节点',key:'node_count',minWidth:110},{title:'最近上报',key:'last_report_at',minWidth:200,render:(r:any)=>stamp(r.last_report_at)}]
 return [{title:'节点',key:'name',minWidth:170},{title:'协议',key:'config',minWidth:100,render:(r:any)=>r.config.protocol?.toUpperCase()},{title:'机器',key:'machine_id',minWidth:100,render:(r:any)=>r.machine_id?'#'+r.machine_id:'独立节点'},{title:'倍率',key:'multiplier_milli',minWidth:90,render:(r:any)=>r.multiplier_milli/1000+'×'},{title:'上报',key:'report_interval',minWidth:90,render:(r:any)=>r.report_interval+' 秒'},{title:'最近上报',key:'last_report_at',minWidth:190,render:(r:any)=>stamp(r.last_report_at)},{title:'连接器',key:'connector',minWidth:140,render:(r:any)=>{if(!r.config.connector)return '原生节点';const c=r.status?.connector;const stale=!c?.seen_at||Date.now()-Date.parse(c.seen_at)>45000;const labels:Record<string,string>={ready:r.config.connector.kind==='mtg'?'指标可用':'隧道已连接',starting:'正在连接',unhealthy:'检查失败',stopped:'已停止',queue_blocked:'上报队列阻塞'};return h(NTag,{size:'small',bordered:false,type:!stale&&c.state==='ready'?'success':'warning'},()=>stale?'状态未更新':labels[c.state]||c.state)}},{title:'状态',key:'active',width:90,render:(r:any)=>h(NTag,{size:'small',bordered:false,type:r.active?'success':'default'},()=>r.active?'启用':'停用')},edit]
})
onMounted(load)
</script>
<template><div class="page-heading"><div><span class="eyebrow">{{kind.toUpperCase()}}</span><h1>{{names[kind]}}管理</h1><p>{{descriptions[kind]}}</p></div><div class="button-row"><n-button quaternary :loading="busy" @click="load"><n-icon :component="Refresh"/></n-button><n-button type="primary" @click="open()"><template #icon><n-icon :component="Plus"/></template>新建{{names[kind]}}</n-button></div></div><n-alert v-if="error" type="error" class="space-bottom">{{error}}</n-alert><article class="surface"><div class="section-heading"><div><h2>全部{{names[kind]}}</h2><p>{{rows.length}} 条记录</p></div><n-tag :bordered="false" size="small">{{kind==='machines'?'Machine 模式':kind==='plans'?'手动分配 · 未启用支付':'数据库记录'}}</n-tag></div><n-data-table :columns="columns" :data="rows" :loading="busy" :bordered="false" :scroll-x="kind==='users'?1000:kind==='nodes'?1190:600" :pagination="{pageSize:15}"/><p class="table-note">{{kind==='users'?'停用账号会停止登录与节点下发；已有用量保留。配额是截至到期前的总上限，修改配额不会清空已用量。':kind==='nodes'?'配置需与节点内核、监听端口和证书一致。旧协议上报保留兼容，数据质量单独标记。':kind==='plans'?'套餐标价仅供记录，当前未启用收款。修改套餐不会自动改变已创建用户的额度。':'机器令牌仅在创建时显示，请妥善保存。将节点关联到机器后，机器客户端可同步对应节点。'}}</p></article>
 <n-modal v-model:show="show" preset="card" class="resource-modal" :title="(editing?'编辑':'新建')+names[kind]" :bordered="false"><n-alert v-if="formError" type="error" class="space-bottom">{{formError}}</n-alert><n-form label-placement="top" @submit.prevent="save">
  <n-form-item v-if="kind!=='users'" label="名称"><n-input v-model:value="form.name" :maxlength="100" placeholder="为它取个便于识别的名字"/></n-form-item>
  <template v-if="kind==='users'"><n-form-item v-if="!editing" label="邮箱"><n-input v-model:value="form.email" :input-props="{type:'email',autocomplete:'off'}"/></n-form-item><n-form-item :label="editing?'重设密码（留空则保持不变）':'密码（12–72 字节）'"><n-input v-model:value="form.password" type="password" show-password-on="click" :input-props="{autocomplete:'new-password'}"/></n-form-item><div v-if="!editing" class="form-two"><n-form-item label="角色"><n-select v-model:value="form.role" :options="[{label:'普通用户',value:'user'},{label:'管理员',value:'admin'}]"/></n-form-item><n-form-item label="套餐（可选）"><n-select v-model:value="form.plan_id" clearable :options="plans.map(x=>({label:x.name,value:x.id}))" placeholder="手动设置额度"/></n-form-item></div><template v-if="editing||!form.plan_id"><n-form-item label="总额度（GiB）"><n-input-number v-model:value="form.quota_gib" :min="0" :max="1048576" :precision="2" style="width:100%"/></n-form-item><n-form-item label="到期时间（浏览器本地时间）"><n-date-picker v-model:value="form.expiry" type="datetime" clearable style="width:100%"/></n-form-item></template><n-form-item v-if="editing" label="账号启用"><n-switch v-model:value="form.active"/></n-form-item></template>
  <template v-if="kind==='plans'"><div class="form-two"><n-form-item label="额度（GiB）"><n-input-number v-model:value="form.quota_gib" :min="0" :max="1048576"/></n-form-item><n-form-item label="有效天数"><n-input-number v-model:value="form.days" :min="1" :max="3650" :precision="0"/></n-form-item></div><n-form-item label="标价（元，仅记录）"><n-input-number v-model:value="form.price" :min="0" :max="1000000" :precision="2"/></n-form-item></template>
  <template v-if="kind==='nodes'"><ProtocolPreset @config="form.config=$event"/><n-form-item label="对外域名或 IP（用于订阅）"><n-input v-model:value="form.public_host" placeholder="node.example.com，不带协议前缀"/></n-form-item><div class="form-two"><n-form-item label="归属机器"><n-select v-model:value="form.machine_id" clearable :options="machines.map(x=>({label:x.name,value:x.id}))" placeholder="独立节点"/></n-form-item><n-form-item label="计费倍率"><n-input-number v-model:value="form.multiplier" :min="0.001" :max="100" :precision="3"/></n-form-item><n-form-item label="上报间隔（秒）"><n-input-number v-model:value="form.interval" :min="10" :max="3600" :precision="0"/></n-form-item><n-form-item label="节点启用"><n-switch v-model:value="form.active"/></n-form-item></div><n-form-item label="节点配置（JSON）"><n-input v-model:value="form.config" type="textarea" :autosize="{minRows:8,maxRows:16}" class="code-input"/></n-form-item><n-alert type="info">生成预设后请检查下方 JSON。需要证书的组合须在节点上准备对应文件；REALITY / ENC 等私密配置需要部署 LUMA_MASTER_KEY。H3 和 Hysteria2 需要开放 UDP 端口，单节点模式的本地内核必须与配置一致。</n-alert></template>
 </n-form><template #footer><div class="modal-footer"><n-button @click="show=false">取消</n-button><n-button type="primary" :loading="saving" @click="save">保存{{names[kind]}}</n-button></div></template></n-modal>
 <n-modal v-model:show="secretVisible" preset="card" class="resource-modal" title="保存连接令牌" :bordered="false"><n-alert type="warning" class="space-bottom">令牌只显示这一次。关闭后无法再次读取，请先保存到安全位置。</n-alert><p>{{names[kind]}} ID：<strong>{{secretID}}</strong></p><n-input :value="secret" readonly type="textarea" :autosize="{minRows:2}" class="code-input"/><template #footer><div class="modal-footer"><n-button @click="secretVisible=false;secret=''">已保存，关闭</n-button><n-button type="primary" @click="copy"><template #icon><n-icon :component="Copy"/></template>复制令牌</n-button></div></template></n-modal>
</template>
